/* GENERATED by tools/gen-data.js from the design (docs/slice-dialogue.md; tools/v6/scenes.js; systems.md §10). Do not edit: change the design's tool and run it again. */
export const SCRIPT6={"1.1":{"id":"1.1","title":"Morning (the bakery) · new game · sets `act 1`","items":[{"dir":"Morning. The bakery smells of volcano fire. Mallow slides two buns across the counter.","show":true},{"who":"Mallow","text":"Two buns, {hero}. Same as every morning."},{"who":"{hero}","text":"Same as every morning. Good. I like things the same."},{"who":"Mallow","text":"So does my oven. It's older than me and twice as stubborn."},{"who":"Mallow","text":"Before you eat those: the cellar's got rats again. Take your stick."},{"who":"{hero}","text":"It's a very good stick."},{"who":"Mallow","text":"It's a stick, dear."}]},"1.2":{"id":"1.2","title":"The cellar (the bakery cellar) · `act 1` · set-piece fights 1 and 2: rats (Pip alone, no class yet: his stick)","items":[{"dir":"{hero} goes down the hatch. Three rats are in the flour sacks. Moving and attacking are taught here.","show":false},{"who":"{hero}","text":"Out. This flour is for buns, and the buns are for me."},{"dir":"A bigger rat noses out from behind the boarded door in the wall, with two friends. The hit chance on each foe is taught here.","show":false},{"who":"{hero}","text":"You're the boss rat, aren't you. You've got a boss face."},{"dir":"After the second fight {hero} looks at the old door, boarded over.","show":true},{"who":"Mallow","text":"(from the hatch) That's the flour tunnel. The carts used to come in under my bakery, before the roads."},{"who":"{hero}","text":"Why doesn't anyone use it?"},{"who":"Mallow","text":"It's full of rats."},{"who":"{hero}","text":"It WAS full of rats."},{"who":"Mallow","text":"Then it's a very good stick."},{"who":"Mallow","text":"Now, one more job. Light my lamp at the tower fire, would you?"},{"who":"Mallow","text":"Tomorrow is hatching day. The embers come out of my oven."},{"who":"Mallow","text":"And my oven wants a proper flame."},{"dir":"Sets `act 2`.","show":false}]},"1.3":{"id":"1.3","title":"The square (Bib's bench) · `act 2`","items":[{"who":"Bib","text":"{hero}! Morning. Sit down, the bench is warm."},{"who":"{hero}","text":"Can't. Errand. Lamp. Tower."},{"who":"Bib","text":"Hatching day tomorrow. Three eggs in the Nest. Everyone's talking about it."},{"who":"{hero}","text":"Are you going?"},{"who":"Bib","text":"Maybe. If I'm up. Here, have a bun. I had three."},{"who":"{hero}","text":"You're the best friend a kobold ever had."},{"who":"Bib","text":"I know. I once asked the whole town to fix the old mill with me. Nobody came."},{"who":"Bib","text":"It was fine. Everything's fine."},{"dir":"Bib's bench can be visited at any time in act 1; after this scene he says one of these (in turn):","show":true},{"who":"Bib","text":"Buns are fine, {hero}. Buns are always fine."},{"who":"Bib","text":"I'd help, but I'm sitting. You can't help AND sit. I've tried."},{"who":"Bib","text":"The fountain's nice today. It was nice yesterday too."}]},"1.4":{"id":"1.4","title":"The castle yard (the drill) · `act 2` · set-piece fights 3 and 4: the recruits, then the sergeant; the class is picked here","items":[{"dir":"The castle gate. Two guards, yawning.","show":true},{"who":"Guard","text":"Halt. Who goes there? (squints) Oh. It's the bun kid."},{"who":"Guard","text":"Go on, then. Mind the drill."},{"dir":"In the yard, a sergeant is shouting at recruits. Snatchclaw watches from the wall.","show":true},{"who":"Sergeant","text":"YOU. Small one. Pick up something and show me what you are."},{"dir":"The class picker opens: fighter, barbarian, paladin, ranger, rogue, monk, cleric, druid, bard, wizard, sorcerer, warlock","show":false},{"who":"Sergeant","text":"Not bad. For a kobold who eats that many buns. Now try ME."},{"dir":"The second bout: the sergeant and one recruit. It teaches the telegraphed big swing (\"he's winding up, step away\").","show":false},{"who":"Sergeant","text":"(winding up) AND... SWING."},{"dir":"After the bout:","show":false},{"who":"Sergeant","text":"Hm. You moved. Most of them just stand there and take it."},{"who":"Snatchclaw","text":"(from the wall) Up early, bun boy? Good. Somebody should be."},{"who":"{hero}","text":"Who's that?"},{"who":"Guard","text":"The captain. Twenty winters on that wall. Never seen him sleep."}]},"1.5":{"id":"1.5","title":"The castle hall and the tower · `act 2`","items":[{"dir":"The hall, on the way to the tower stairs. A faded mural: kobolds carrying fire up a mountain, and at the front a kobold","show":true},{"who":"{hero}","text":"Doesn't look like it smiles. Looks like a pipe."},{"dir":"The tower fire at the top. {hero} holds out the lamp; the flame jumps into it.","show":true},{"who":"Tower guard","text":"Every hearth in Kobaldia was lit from that fire. Your baker's oven too."},{"who":"Tower guard","text":"Don't drop it."},{"who":"{hero}","text":"I never drop things. (He nearly drops it.)"},{"dir":"Back at the bakery, Mallow lights the oven from the lamp. Sets `act 3`. Night falls; {hero} sleeps.","show":true}]},"1.6":{"id":"1.6","title":"Hatching day (the bakery, then the square) · `act 3`","items":[{"dir":"Morning. Mallow lifts glowing embers out of the oven with tongs, one into each clay cup.","show":true},{"who":"Mallow","text":"Here, {hero}. Your ember. Keep it close, you chilly little lizard."},{"who":"{hero}","text":"It's warm."},{"who":"Mallow","text":"That's the idea. Take it to the Nest and warm whichever egg you think best."},{"who":"{hero}","text":"What if they're all bad?"},{"who":"Mallow","text":"Then pick the least bad, dear. That's most of life."},{"dir":"In the square only a handful of kobolds hold clay cups. Most are still in bed.","show":true}]},"1.7":{"id":"1.7","title":"The Great Nest (the castle yard) · `act 3`","items":[{"dir":"Three big eggs in the straw: a green one with little shoots, a grey one that seems to yawn, and a gold one on a pile of","show":true},{"who":"Bramble","text":"That's the sprouty one. More buns, and everybody helps at harvest."},{"who":"Bramble","text":"Work never hurt a kobold."},{"who":"Mallow","text":"I'm warming the sleepy one. My oven's old. A sleepy dragon keeps things as they are."},{"who":"Glint","text":"Look at it SHINE. It's got a RIBBON."},{"who":"Smudge","text":"The finest buns, friend! A sticker for everyone who warms the shiny one. Sticker?"},{"who":"{hero}","text":"No."},{"who":"Smudge","text":"Suit yourself. (to Glint) Sticker?"},{"who":"Glint","text":"(already holding out his ember) Yes please."},{"who":"Bramble","text":"Any of them will keep the raiders off the border."},{"who":"Bramble","text":"Dwarves, elves, humans. They all want our buns."},{"who":"Bramble","text":"The difference is who gets the buns afterwards."},{"dir":"The player can look at each egg (one line each):","show":true},{"who":"{hero}","text":"(sprouty) It's growing a leaf. Show-off."},{"who":"{hero}","text":"(sleepy) It's asleep. I respect that."},{"who":"{hero}","text":"(shiny) It's wearing a ribbon. Eggs shouldn't wear things."},{"dir":"Sets `act 4`.","show":false}]},"1.8":{"id":"1.8","title":"Why bother? (the Nest) · `act 4` · the refusal","items":[{"dir":"{hero} walks to the sprouty egg, cup in hand. Bib wanders up behind him.","show":true},{"who":"Bib","text":"{hero}. Why bother? A dragon's a dragon. You've got your buns."},{"who":"Bib","text":"Here. Have mine too."},{"who":"{hero}","text":"(looks at the bun, then the egg, then the bun) ...It's still warm."},{"dir":"{hero} pockets his ember, sits down in the warm straw and eats Bib's bun. He falls asleep.","show":true},{"dir":"Night. Almost nobody comes. Three guards walk in and hold their embers to the shiny egg.","show":true},{"who":"Guard","text":"Captain says the shiny one."},{"who":"Guard","text":"Captain says."},{"dir":"Glint is asleep next to the shiny egg, his sticker on his nose. The gold egg glows.","show":true},{"dir":"Dawn. CRACK.","show":true},{"who":"Glitterbeak","text":"...Cold. COLD. Why is everything so COLD?"},{"dir":"He sees Mallow's tray of morning buns, steaming. He eats the whole tray.","show":true},{"who":"Glitterbeak","text":"Warm. MINE."},{"dir":"He flies to the castle roof. {hero} wakes up with straw in his ear.","show":true},{"who":"{hero}","text":"What did I miss?"},{"dir":"Sets `act 5`. A notice goes up on the bakery: EVERY BATCH TO THE GUARDS FIRST.","show":false}]},"1.9":{"id":"1.9","title":"Somebody did (the bakery) · `act 5` · the mentor","items":[{"who":"{hero}","text":"Every batch to the guards? But I didn't choose any of this."},{"who":"Mallow","text":"No, dear. Somebody did."},{"dir":"Silence. Mallow kneads an empty bowl. Then she takes off her hat; there's a bun in it.","show":true},{"who":"Mallow","text":"One left. I hid it in my hat. Don't tell the dragon."},{"dir":"Mallow's bun (1 of 3) goes in the bag.","show":true},{"who":"Mallow","text":"(singing, quietly) When a dragon hatches cold, and he hoards the buns and gold..."},{"who":"{hero}","text":"I know that one. It's for babies."},{"who":"Mallow","text":"It's for everybody. (She takes down a fat recipe book.) My grandmother's."},{"who":"Mallow","text":"Recipes in the front. In the back, instructions for a thing called the Smiler."},{"who":"Mallow","text":"A piece in every town. Bring them together and you can fix a dragon that hatched wrong."},{"who":"{hero}","text":"So somebody should go and get them."},{"who":"Mallow","text":"Somebody should."},{"who":"{hero}","text":"...I'm going to Pebblebrook for flour. For buns. That's all."},{"who":"Mallow","text":"Of course you are, dear. Take the book."},{"dir":"Wizzle bursts in.","show":true},{"who":"Wizzle","text":"I'm COMING. I'm too young for an ember but I am NOT too young for this."},{"who":"Glint","text":"(in the doorway, sticker still on) I warmed the shiny one. For a sticker. ...I'll come too."},{"who":"{hero}","text":"Fine. Nobody talk to me before lunch."},{"dir":"Wizzle and Glint join. Sets `act 6`. The inn's first two campfire chats unlock (§6).","show":false}]},"1.10":{"id":"1.10","title":"Hearthspire's people in act 1 (one line each, by place)","items":[{"who":"Fountain kobold","text":"Hatching day! I'll go after my nap. (after the hatching:) Did I miss it? I missed it."},{"who":"Smith","text":"Sticks, swords, pans. A pan is a sword for buns."},{"who":"Moon shrine keeper","text":"Forget what you learned, little one? The moon remembers it for you. For a few coins."},{"who":"Shopkeeper","text":"Potions on the left, buns on the right. (after the hatching:) Potions on the left. Just potions now."},{"who":"Innkeeper","text":"A bed's ten gold, the fire's free, and the stories are worth what you pay for them."},{"who":"Barracks guard","text":"We're on the wall all night, every night. You lot sleep. That's fine. Somebody has to."},{"who":"Market board","text":"\"Lost: one sock. Warm.\""},{"who":"Market board","text":"\"Raptor rides to Pebblebrook: SUSPENDED. No flour, no feed.\""}]},"1.11":{"id":"1.11","title":"The capital gate · `act 6` · the threshold","items":[{"who":"Gate guard","text":"Going out? One bun. New rule."},{"who":"{hero}","text":"I haven't got a bun."},{"who":"Gate guard","text":"Then the next one you get is ours. (Flavour only: nothing leaves the bag, `design.md` §2.)"},{"who":"{hero}","text":"That was going to be my lunch."},{"who":"Gate guard","text":"It's the dragon's lunch now. He's a growing lad."},{"dir":"A kobold sits cross-legged by the gate, eyes shut.","show":true},{"who":"Bork","text":"Bork is meditating."},{"who":"Wizzle","text":"He's asleep."},{"who":"Bork","text":"(opens one eye) Bork napped through the hatching. Bork is... ashamed."},{"who":"Bork","text":"Bork would like to come. Bork will not nap."},{"who":"{hero}","text":"We're going for flour. Nothing more."},{"who":"Bork","text":"Bork likes flour. (nods off; Wizzle pokes him; he joins)"},{"dir":"Bork joins. Outside the gate, three Nettlenose scouts are pulling at a flour cart that isn't there any more.","show":false}]},"1.12":{"id":"1.12","title":"Outside the gate · `act 6`, after Bork joins · set-piece fight 5: Nettlenose scouts (the first fight with a pack of four; R1's newest foe)","items":[{"who":"Nettlenose scout","text":"Oi! Toll! Snatchclaw's orders! ...Have you got flour?"},{"who":"{hero}","text":"We're GOING for flour."},{"who":"Nettlenose scout","text":"Then we'll toll you on the way back!"},{"dir":"After the fight they scamper off down R1.","show":true},{"who":"Glint","text":"They had shiny buttons. Did anyone else see the buttons?"},{"dir":"Sets `act 7`: R1 is open.","show":false}]},"2.0":{"id":"2.0","title":"R1 (the capital gate → Pebblebrook)","items":[{"dir":"Signs and small scenes, in the order they're met.","show":true},{"who":"Sign","text":"PEBBLEBROOK 120 steps. Beetles."},{"who":"Sign by the pond","text":"NO SWIMMING (beetles)."},{"who":"Raptor stable sign","text":"RAPTOR STABLE. Shut. No flour, no feed, no raptors. Sorry. —The Riders"},{"who":"Grubb's sign","text":"TOLL: one bun. Or two. I'm flexible."}]},"2.1":{"id":"2.1","title":"The runaway goat (route extra) · any time","items":[{"who":"Goat","text":"Meh."},{"dir":"It follows the pack. It eats a sign. At the Mossback farms in Pebblebrook:","show":false},{"who":"Farmer Clover","text":"BUTTERCUP! You found her! She ate my gate again, didn't she."},{"who":"{hero}","text":"She ate a sign."},{"who":"Farmer Clover","text":"Progress. Here, take this ring, it's lucky. Buttercup never liked it."}]},"2.2":{"id":"2.2","title":"Tansy's lunch (the pond) · challenge step 2 · needs `pb ≥ 2`","items":[{"who":"Tansy","text":"I'm not going ANYWHERE hungry. I put my lunch down for one moment."},{"who":"Tansy","text":"One moment. And a beetle took it. Into the reeds."},{"dir":"A fight with a copper beetle and its friends in the tall grass by the pond.","show":true},{"who":"{hero}","text":"Your lunch. Slightly chewed."},{"dir":"A choice appears: \"Give it back\" or \"Eat it\" (a deed, `corruption.md` #9: +2 corruption; \"Give it back\" is kind deed 3, −1). Eating it:","show":true},{"who":"Tansy","text":"You ATE it? ...Fine. I'm still coming. I'm not happy about it."},{"dir":"Either way she comes; the line below is for \"Give it back\".","show":false},{"who":"Tansy","text":"(inspecting it) That's beetle chewing. Fine. I'll come to the circle."},{"who":"Tansy","text":"I'm eating it on the way, though."}]},"3.1":{"id":"3.1","title":"Arrival (the mill road, Grubb's toll) · `act 7` · sets `pb 1`","items":[{"dir":"A big kobold in a guard's helmet sits on a box across the mill road.","show":true},{"who":"Grubb","text":"HALT. Toll. One bun."},{"who":"{hero}","text":"The gate's already got my next one."},{"who":"Grubb","text":"Then you owe one. I'm writing it down. (He writes it down. It takes a while.)"},{"who":"Grubb","text":"Go on in. And stay off my mill road on the way out."},{"who":"Grubb","text":"Flour carts don't leave without paying."},{"who":"Sign","text":"PEBBLEBROOK. Home of the best flour in Kobaldia. (Flour currently unavailable.)"},{"dir":"The mill wheel stands still. Nobody is at the circle stones; on the biggest one, a chalk tally of marks.","show":true}]},"3.2":{"id":"3.2","title":"Ruddle (the mill) · `pb 1` · sets `pb 2` (the challenge opens)","items":[{"who":"Ruddle","text":"You're from the capital? Come for flour? Ha. Have a look at the wheel."},{"who":"{hero}","text":"It's not turning."},{"who":"Ruddle","text":"The dam's shut. The brook goes round my mill instead of through it."},{"who":"{hero}","text":"So open the dam."},{"who":"Ruddle","text":"Not alone, I can't. The dam is the whole town's. The shift circle decides it."},{"who":"Ruddle","text":"Everyone in the circle drops a stone in the bag. White, open it. Black, leave it."},{"who":"Ruddle","text":"Last spring the bag said leave it. By one stone."},{"who":"{hero}","text":"So do it again."},{"who":"Ruddle","text":"With what circle? The miners haven't sat in it in nine years."},{"who":"Ruddle","text":"I've been counting. On the stone."},{"who":"Ruddle","text":"Get the whole shift to the circle and we'll try again. Five of them."},{"who":"Ruddle","text":"Well. Four who might come. And one who never does."},{"who":"{hero}","text":"Why me?"},{"who":"Ruddle","text":"You're the only one in town who hasn't said \"why bother\" yet."},{"who":"{hero}","text":"(who nearly did) ...Fine. Who are they?"},{"who":"Ruddle","text":"Ore, down the mine. Tansy, out by the pond."},{"who":"Ruddle","text":"Flint and Grit, who aren't speaking. And Old Marl."},{"dir":"The quest log lists the five miners as five lines (one per step) with a hint each, one tap away.","show":false},{"who":"Ruddle","text":"A smiler? Never heard of one. A flute, maybe. For a very big kobold.","when":"if asked about the Smiler"},{"who":"Ruddle","text":"Old things? The only old thing here is my axle. Stuck since my grandad's day."}]},"3.3":{"id":"3.3","title":"Grubb (the mill road) · `pb ≥ 2`, when the player walks onto the mill road · boss, L5","items":[{"who":"Grubb","text":"I SAID stay off my mill road."},{"who":"{hero}","text":"There's nothing to carry anyway. The mill's stopped."},{"who":"Grubb","text":"Then nothing pays nothing. That's still a toll."},{"dir":"Fight. Grubb swings big every third round, and shouts first.","show":false},{"who":"Grubb","text":"(winding up) HERE IT COMES."},{"dir":"After:","show":false},{"who":"Grubb","text":"Fine. FINE. Keep your road. (He takes his toll box and stomps off toward town, not the capital.)"},{"who":"Wizzle","text":"He went the wrong way. The capital's that way."},{"who":"{hero}","text":"Not my problem."},{"dir":"Sets `grubb 1`. The mill road is open; the raptor stable is still shut (no feed).","show":false}]},"3.4":{"id":"3.4","title":"Glitterbeak over the mill · after `grubb 1`, the next time the player comes to the mill","items":[{"dir":"A shadow slides over the mill. Glitterbeak lands on the roof and sniffs at the flour sacks in the loft window.","show":true},{"who":"Glitterbeak","text":"Mine. Mine. Mine. Mine. (He loses count.) ...Mine."},{"who":"Glitterbeak","text":"(shivering) Still cold."},{"dir":"He flies off. Where he sat, the roof is white with frost.","show":true},{"who":"Ruddle","text":"Third time this month. He doesn't even eat flour. He just likes to count it."}]},"3.5":{"id":"3.5","title":"Ore and Nugget (mine floor 1) · challenge step 1","items":[{"dir":"Near the stairs, a small kobold is arguing with a lantern seller who isn't there any more.","show":true},{"who":"Nugget","text":"Three copper for the lantern. For you, four."},{"who":"{hero}","text":"That's more."},{"who":"Nugget","text":"You look like you can afford it. Everything has a price."},{"who":"Nugget","text":"You're going deeper? You'll want a lantern. I have a lantern."},{"who":"Nugget","text":"I'll come WITH the lantern. Nine copper a day."},{"who":"{hero}","text":"No."},{"who":"Nugget","text":"Eight."},{"who":"Bork","text":"Bork has no copper."},{"who":"Nugget","text":"...Fine. Free. Just this once. Don't tell anybody."},{"who":"Nugget","text":"And if you see a nugget shaped like a duck, it's my grandad's. It's mine."},{"dir":"Nugget joins (he also brings a 5% discount at shops). At the end of the rails, a full cart is jammed.","show":false},{"who":"Ore","text":"Don't touch that cart. A full cart off the rails is a cart in the face."},{"who":"Ore","text":"I can't leave it, I can't move it, so I'm standing here. That's mining."},{"dir":"The rail puzzle: switch the points so the cart rolls back to the rail end.","show":true},{"who":"Ore","text":"Huh. Rolled right back. ...The circle? Nine years. Is Ruddle still counting?"},{"who":"{hero}","text":"On the stone."},{"who":"Ore","text":"Somebody has to sit on the big stone. Might as well be me."}]},"3.6":{"id":"3.6","title":"The one stone (the mill loft) · challenge step 3, and the side quest \"The one stone\"","items":[{"dir":"Flint and Grit stand at opposite ends of the square, not looking at each other.","show":true},{"who":"Flint","text":"He dropped it. The stone. On the way to the bag. That's why it lost."},{"who":"Grit","text":"HE dropped it."},{"who":"Flint","text":"Did not."},{"who":"Grit","text":"Did."},{"who":"{hero}","text":"Where's the bag now?"},{"who":"Flint and Grit","text":"(pointing at the mill) Loft."},{"dir":"In the mill loft, the old bag hangs on a nail. There's a hole in the bottom. A white stone sits under it.","show":true},{"who":"{hero}","text":"Nobody dropped it. The bag did."},{"who":"Flint","text":"...Stupid bag."},{"who":"Grit","text":"Stupid bag."},{"who":"Flint","text":"We'll come. We're bringing our own bag."},{"who":"Grit","text":"I'm holding it."},{"who":"Flint","text":"I'M holding it."},{"dir":"The loft chest can be opened now (its key was in the bag).","show":false}]},"3.7":{"id":"3.7","title":"Old Marl (her house, then the mill) · challenge step 4","items":[{"who":"Old Marl","text":"The circle never listens. Nine years ago I stood up to speak and they'd already decided."},{"who":"Old Marl","text":"So I stopped going. Nobody noticed. That's how you know."},{"dir":"{hero} goes to the mill.","show":true},{"who":"{hero}","text":"Old Marl will come if she can speak first."},{"who":"Ruddle","text":"First? (a long pause) Yes. Of course. I should have said that nine years ago."},{"dir":"Back at Marl's house:","show":false},{"who":"Old Marl","text":"First? Hm. Then I'll come. And I'll be long."}]},"3.8":{"id":"3.8","title":"The fifth miner (the circle stones, at dusk) · after steps 1–4 · the twist","items":[{"dir":"Dusk. Someone sits alone in the empty circle, a toll box under his arm. It's Grubb, on the smallest stone.","show":true},{"who":"Grubb","text":"This was my stone. Before the helmet."},{"who":"{hero}","text":"You're from HERE?"},{"who":"Grubb","text":"Born by the dam. Nine years ago I said the dam was going to need fixing. Nobody listened."},{"who":"Grubb","text":"So I went where they do listen. The guards gave me a box and a road."},{"who":"Grubb","text":"Everybody listens to a toll."},{"who":"{hero}","text":"You're the one who never comes."},{"who":"Grubb","text":"Why would I? (He gets up and walks off into the dark.)"},{"who":"Ruddle","text":"(arriving with a lantern) So you've met our fifth."},{"who":"Ruddle","text":"Snipe's down the mine taking half the copper. Deal with him first."},{"who":"Ruddle","text":"Then we'll see about Grubb."},{"dir":"Sets `pb 3`.","show":false}]},"3.9":{"id":"3.9","title":"Snipe (mine floor 3) · `pb 3` · boss, L8","items":[{"dir":"A guard on a copper cart, behind a pile of copper.","show":true},{"who":"Snipe","text":"Half the copper for the guards. Half the half for me."},{"who":"Snipe","text":"The rest for the miners. That's sums."},{"who":"{hero}","text":"That's not sums."},{"who":"Snipe","text":"It's MY sums."},{"dir":"Fight. Snipe rolls behind cover on his cart.","show":false},{"dir":"After:","show":false},{"who":"Snipe","text":"Fine! Take it! Copper's heavy anyway."},{"who":"Nugget","text":"(already filling his pockets) Is it, though?"},{"who":"{hero}","text":"Put it back. It's the miners'."},{"who":"Nugget","text":"...I was counting it. For them."},{"dir":"Sets `pb 4`. The flooded gallery (the hidden trial, Old Shellback) is next to Snipe's pile; it has no lines.","show":false}]},"3.10":{"id":"3.10","title":"Grubb's stone (the toll box) · `pb 4` · challenge step 5","items":[{"dir":"Grubb sits on his toll box on the mill road. {hero}, Nugget and Old Marl walk up together.","show":true},{"who":"Old Marl","text":"Grubb. I'm speaking first today. I'd like you to hear it."},{"who":"Grubb","text":"You lot never let anybody speak first."},{"who":"Old Marl","text":"We do now. Ruddle said."},{"who":"Nugget","text":"And the toll box is worth nothing. I checked. It's empty."},{"who":"Grubb","text":"(looks in the box; it's empty) ...It's always been empty. Nobody paid."},{"who":"Grubb","text":"(puts the helmet in the box) My stone's still there?"},{"who":"{hero}","text":"Smallest one."},{"who":"Grubb","text":"It was always the smallest one."},{"dir":"Sets `pb 5`.","show":false}]},"3.11":{"id":"3.11","title":"The circle meets (the circle stones) · `pb 5` · the reconciliation","items":[{"dir":"The whole shift sits on the stones: Ore on the big one, Tansy eating, Flint and Grit holding one bag together, Grubb","show":true},{"who":"Old Marl","text":"I've waited nine years to say this. The dam leaks on the east side."},{"who":"Old Marl","text":"That's all. That's what I wanted to say. Sit down, Marl."},{"who":"Ruddle","text":"Stones in the bag. White, open it. Black, leave it."},{"dir":"One by one they drop stones in. Ruddle tips the bag out on the big stone. All white.","show":true},{"who":"Ruddle","text":"Open. Every stone. Even Grubb's."},{"who":"Grubb","text":"(quietly) Even mine."},{"dir":"Ruddle wipes the chalk tally off the stone with his sleeve.","show":true}]},"3.12":{"id":"3.12","title":"The wheel turns, the tube (the mill) · after the circle · sets `pb 6`","items":[{"dir":"The dam opens, the brook runs through the mill and the wheel groans. Something clanks inside.","show":true},{"who":"Ruddle","text":"That's the old axle. It's come loose. (He pulls out a long iron tube with a smile cut into one end.)"},{"who":"{hero}","text":"(opening Mallow's book) \"The tube.\" That's a piece. That's a Smiler piece."},{"who":"Ruddle","text":"Take it. It never turned right anyway."},{"who":"Nugget","text":"That's worth at least—"},{"who":"{hero}","text":"No."},{"dir":"The first Smiler piece. The raptor stable opens on the mill road.","show":true},{"who":"Rider","text":"Flour-feed's back! Raptors are flying! Well. Running. They don't fly. Hop on."},{"dir":"Raptor travel is unlocked.","show":false}]},"3.13":{"id":"3.13","title":"Pebblebrook's people (one or two lines each)","items":[{"who":"Innkeeper","text":"Beds upstairs, the fire's down here. We don't have flour, so the pies are just crust."},{"who":"Innkeeper","text":"Pies are back. Real ones. With insides.","when":"after the mill turns"},{"who":"Shopkeeper","text":"Picks, lamps, and swords that were picks once."},{"who":"Smith","text":"Bring me five scraps of gold and I'll make you miller's boots."},{"who":"Smith","text":"Very good for standing still in."},{"who":"Ruddle's apprentice","text":"I chalk a new mark every morning. Nine years. Nearly ran out of stone."},{"who":"Farmer at the fountain","text":"The guards say the toll keeps the raiders off."},{"who":"Farmer at the fountain","text":"Can't see how. Raiders don't use the mill road."},{"who":"Note board","text":"\"Ghost in the mill!!\""},{"who":"Note board","text":"\"Anyone seen Buttercup? (goat)\""},{"who":"Note board","text":"\"BOUNTY: Big Pinch\" · \"BOUNTY: Nettlenose scout leader\""}]},"3.14":{"id":"3.14","title":"Side quests and bounties","items":[{"dir":"The ghost of the mill (funny). A kobold by the mill, shaking.","show":true},{"who":"Shaky kobold","text":"There's a GHOST in the mill. All white. It goes skree."},{"dir":"In the mill: a raptor chick, covered head to toe in flour.","show":true},{"who":"Raptor chick","text":"Skree."},{"who":"{hero}","text":"It's a chick. In flour."},{"who":"Rider","text":"(later) We'll keep her. She's already named. She's called Ghost."},{"dir":"Seed swap (the land). A Mossback farmer at the farms.","show":true},{"who":"Farmer Clover","text":"Moss tufts! Bring me three and I'll give you seeds."},{"who":"Farmer Clover","text":"Moss for seeds, seeds for moss. That's farming."},{"dir":"After:","show":false},{"who":"Farmer Clover","text":"Here, a cape. It's moss. It's warm. You'd be amazed what moss can do."},{"who":"Board","text":"BIG PINCH. A copper beetle the size of a cart. Eats boots. Reward 40 gold."},{"who":"Board","text":"A Nettlenose with a sergeant's hat. Says he's the guard"},{"who":"Nettlenose scout leader","text":"I'm the sergeant's cousin! I have a hat!"}]},"6.0":{"id":"6.0","title":"The slice's campfire chats","items":[{"dir":"Chats play at an inn when everyone in them is in the pack (`companions.md`). Each gives +1 bond to every companion in it.","show":true}]},"6.1":{"id":"6.1","title":"You HAD one?! (Wizzle) · Hearthspire inn, after §1.9","items":[{"who":"Wizzle","text":"{hero}. You had an ember. A real one. From Mallow."},{"who":"{hero}","text":"Still have it."},{"who":"Wizzle","text":"You HAD one and you KEPT it?!"},{"who":"{hero}","text":"I was going to use it. I got a bun."},{"who":"Wizzle","text":"I'd have given ANYTHING for an ember. I'd have given you my tail."},{"who":"{hero}","text":"I don't want your tail."},{"who":"Wizzle","text":"Nobody ever wants my tail. Grandma says I'm too young to count."},{"who":"{hero}","text":"You're counting now. You're coming, aren't you?"},{"who":"Wizzle","text":"(quiet for once) ...Yeah."}]},"6.2":{"id":"6.2","title":"The sticker (Glint) · Hearthspire inn, after §1.9","items":[{"who":"Glint","text":"Want to see my sticker?"},{"who":"{hero}","text":"No."},{"who":"Glint","text":"It's a dragon. With a ribbon. It shines when you tilt it."},{"who":"{hero}","text":"That's the dragon who ate Mallow's tray."},{"who":"Glint","text":"(tilting it) He looks so friendly on the sticker."},{"who":"{hero}","text":"He's on the castle roof stealing buns."},{"who":"Glint","text":"...I didn't know it was that kind of shiny."},{"who":"Glint","text":"I'll keep it anyway. I keep everything shiny. It's the only thing I'm good at."}]},"6.3":{"id":"6.3","title":"Bork is meditating (Bork) · Pebblebrook inn","items":[{"who":"Bork","text":"Bork is meditating."},{"who":"{hero}","text":"You're snoring."},{"who":"Bork","text":"Bork meditates loudly."},{"who":"Bork","text":"(awake) On hatching night Bork lay down for one minute. To rest his eyes."},{"who":"Bork","text":"When Bork opened them there was a dragon. And no buns."},{"who":"Wizzle","text":"You slept through the WHOLE THING?"},{"who":"Bork","text":"Bork slept through the whole thing."},{"who":"Bork","text":"Bork will not nap through anything again. (He yawns.) Starting tomorrow."}]},"6.4":{"id":"6.4","title":"Everything has a price (Nugget) · Pebblebrook inn, after §3.5","items":[{"who":"Nugget","text":"How much do you want for the stick?"},{"who":"{hero}","text":"It's not for sale."},{"who":"Nugget","text":"Everything has a price. Even you."},{"who":"{hero}","text":"What's my price?"},{"who":"Nugget","text":"(looks him up and down) Two buns. Every morning. You'd be cheap."},{"who":"{hero}","text":"(says nothing for a while)"},{"who":"Nugget","text":"It was a joke. Mostly. I'd pay three."}]},"6.5":{"id":"6.5","title":"Who deserves an ember (Wizzle and Nugget) · Pebblebrook inn, after §3.9","items":[{"who":"Wizzle","text":"The miners all have embers. Every one. Even the brothers who don't talk."},{"who":"Nugget","text":"Everybody grown has one. You get one from the tower fire. That's how it works."},{"who":"Wizzle","text":"Well I think you should have to DESERVE it."},{"who":"Nugget","text":"Who decides who deserves it?"},{"who":"Wizzle","text":"...Somebody clever."},{"who":"Nugget","text":"Like who?"},{"who":"Wizzle","text":"(thinks hard) Me."},{"who":"Nugget","text":"I'd sell mine to you. Price on request."},{"who":"Wizzle","text":"You can't SELL an ember!"},{"who":"Nugget","text":"Then what's it for?"},{"dir":"Neither of them knows. They both look at {hero}'s pocket. {hero} pretends to be asleep.","show":true}]}};
